CREATE TABLE p_member_invitations(email TEXT PRIMARY KEY,request_id TEXT NOT NULL UNIQUE,role TEXT NOT NULL CHECK(role IN ('admin','manager','sales','content_editor','viewer','billing')),teams TEXT NOT NULL,issuer_id TEXT NOT NULL REFERENCES oa_operators(id),issuer_native_version INTEGER NOT NULL,issuer_member_version INTEGER NOT NULL,expires_at INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','accepted')),accepted_id TEXT REFERENCES oa_operators(id));
